# Hypothesis: a property inherited through a diamond MRO resolves to A's getter, and d.bar resolves to C.bar before A.bar, so calling d.bar() without its float argument raises TypeError.
from typing import reveal_type


class A:
    def __init__(self) -> None:
        self._name = 'a'

    @property
    def name(self) -> str:
        return self._name

    def foo(self, v1: str) -> str:
        return v1

    def bar(self) -> str:
        return 'A.bar'


class B(A):
    def foo(self, v1: str) -> str:
        return super().foo(v1 + '!')


class C(A):
    def foo(self, v1: str) -> str:
        return v1.upper()

    def bar(self, v1: float) -> str:
        return str(v1)


class D(B, C):
    pass


def call_bar_without_args(obj: D) -> str:
    return obj.bar()  # expect-error


d = D()
reveal_type(d.name)
reveal_type(d.bar)
print(d.name, d.foo('hi'), d.bar(2.5))
print(A.bar(d), A.foo(d, 'x'))
try:
    call_bar_without_args(d)
except TypeError:
    print('TypeError as expected')
